use core::marker::PhantomData;

use crate::{Resource, ResourceKind, sys, text};

/// One rule invocation: the only way to query the network or stage commands.
///
/// Commands are *staged*: they take effect after the rule returns, and all of them are
/// discarded if the rule panics or exceeds a limit (see the crate docs). A `Rule` cannot be
/// created by programs, so host calls outside a rule are compile errors rather than traps.
pub struct Rule {
    // Not Send/Sync, not constructible outside the crate.
    _private: PhantomData<*const ()>,
}

/// A rule's registration, generated by `#[factorycore::program]` as `RULES`.
#[derive(Clone, Copy, Debug)]
pub struct RuleDef {
    /// Persistent rule key, unique within the program.
    pub key: &'static str,
    /// Run interval in game ticks (20 per second), 10..=72,000.
    pub interval_ticks: u32,
    /// The rule body.
    pub run: fn(&Rule),
}

impl Rule {
    pub(crate) const fn new() -> Self {
        Rule {
            _private: PhantomData,
        }
    }

    /// Machine interfaces with this local label, in stable order (at most 64 per label).
    /// Handles are only valid during this rule, which the `'cx` lifetime enforces.
    pub fn machines(&self, label: &str) -> Machines<'_> {
        let (base, count) = sys::machines(label);
        Machines {
            next: base,
            end: base + count,
            _rule: PhantomData,
        }
    }

    /// Units of `resource` currently available in network storage (needs the deployer's View
    /// permission). Energy is in FE, fluids in millibuckets.
    pub fn stock(&self, resource: Resource<'_>) -> u64 {
        sys::stock(resource)
    }

    /// Requests crafting `amount` (1..=1,048,576) of an item; repeated requests for the same
    /// item within one rule are deduplicated by the server.
    ///
    /// # Panics
    /// If `item` is not an [`item`](crate::item).
    pub fn craft(&self, item: Resource<'_>, amount: u32) {
        if item.kind() != ResourceKind::Item {
            panic!("craft needs an item, not {:?}", item.kind());
        }
        sys::craft(item.id(), amount);
    }

    /// Sets every Signal-mode Interface labelled `label` in this network segment to `strength`
    /// (0..=15) while the program stays deployed (language v2, ADR 0062). Stopping or pausing the
    /// program hands them back to their own settings.
    ///
    /// # Panics
    /// If `strength` is over 15.
    pub fn emit_redstone(&self, label: &str, strength: u8) {
        if strength > 15 {
            panic!("redstone strength {strength} is over 15");
        }
        sys::emit(text::truncate(label), strength);
    }

    /// Appends a line to the controller log, cut to 128 bytes. Use [`log!`](crate::log) to
    /// format values.
    pub fn log(&self, text: &str) {
        sys::log(text::truncate(text));
    }

    /// Copies the committed persistent state into `buffer` and returns its full length, or
    /// `None` if this deployment has never saved any. A short buffer receives a prefix.
    pub fn load_state(&self, buffer: &mut [u8]) -> Option<usize> {
        sys::state_read(buffer)
    }

    /// Stages `data` (at most [`MAX_STATE`](crate::MAX_STATE) bytes, else the rule traps) as the
    /// persistent state. It commits only if this rule finishes, survives reloads, and is reset
    /// by a new deployment. Version your own byte layout.
    pub fn save_state(&self, data: &[u8]) {
        sys::state_write(data);
    }

    /// Decodes the committed persistent state as a `T`, or returns `None` if this deployment
    /// has never saved any. Requires the `serde` feature; see [`Rule::set_state`].
    ///
    /// # Panics
    /// If the saved bytes do not decode as a `T`. State is reset by every deployment, so this
    /// only happens when a program saves one type and loads another.
    #[cfg(feature = "serde")]
    pub fn state<T: serde::de::DeserializeOwned>(&self) -> Option<T> {
        let mut buffer = [0; crate::MAX_STATE];
        let len = self.load_state(&mut buffer)?;
        match postcard::from_bytes(&buffer[..len.min(crate::MAX_STATE)]) {
            Ok(value) => Some(value),
            Err(_) => panic!(
                "saved state does not decode as {}",
                core::any::type_name::<T>()
            ),
        }
    }

    /// Stages `value`, encoded with postcard 1.x, as the persistent state, with the same commit
    /// rules as [`Rule::save_state`]. Requires the `serde` feature.
    ///
    /// # Panics
    /// If the encoding is over [`MAX_STATE`](crate::MAX_STATE) bytes.
    #[cfg(feature = "serde")]
    pub fn set_state<T: serde::Serialize + ?Sized>(&self, value: &T) {
        let mut buffer = [0; crate::MAX_STATE];
        match postcard::to_slice(value, &mut buffer) {
            Ok(bytes) => self.save_state(bytes),
            Err(_) => panic!("state over {} bytes when encoded", crate::MAX_STATE),
        }
    }
}

/// A face of the machine block (not of its Interface), for [`Machine::side`].
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
#[repr(i32)]
pub enum Side {
    Down = 0,
    Up = 1,
    North = 2,
    South = 3,
    West = 4,
    East = 5,
}

/// A machine interface selected by label during one rule.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Machine<'cx> {
    handle: i32,
    _rule: PhantomData<&'cx Rule>,
}

impl<'cx> Machine<'cx> {
    /// This machine reached through `side` of the machine block for the moves that use the
    /// returned value (language v2). Another face than the Interface's own needs the Interface
    /// bound to every slot; the server refuses it otherwise.
    pub fn side(self, side: Side) -> Machine<'cx> {
        Machine {
            handle: sys::with_access(self.handle, side as i32, -1, -1),
            _rule: PhantomData,
        }
    }

    /// Only slots `first..=last` of the face used (language v2). On the Interface's own face
    /// they must lie inside its bound window.
    ///
    /// # Panics
    /// If `first > last` or `last` is over 1,023.
    pub fn slots(self, slots: core::ops::RangeInclusive<u16>) -> Machine<'cx> {
        let (first, last) = (*slots.start(), *slots.end());
        if first > last || last > 1_023 {
            panic!("slots {first}..={last} are not a range within 0..=1023");
        }
        Machine {
            handle: sys::with_access(self.handle, -1, first.into(), last.into()),
            _rule: PhantomData,
        }
    }

    /// Moves at most `limit` (1..=4,096) matching units straight from this machine into
    /// `target`, without passing through storage (language v2).
    pub fn move_to(self, target: Machine<'_>, resource: Resource<'_>, limit: u32) {
        sys::move2(self.handle, target.handle, resource, limit);
    }

    /// Matching units this machine holds now, through its Interface's binding. Moves still in
    /// flight are not counted.
    pub fn has(self, resource: Resource<'_>) -> u64 {
        sys::has(self.handle, resource)
    }

    /// Whether this machine's Interface receives redstone power.
    pub fn powered(self) -> bool {
        sys::redstone_in(self.handle)
    }

    /// Requests the deficit so this machine holds `amount` (1..=1,048,576) matching units.
    pub fn keep_stocked(self, resource: Resource<'_>, amount: u32) {
        sys::keep_stocked(self.handle, resource, amount);
    }

    /// Moves at most `limit` (1..=4,096) matching units from this machine into storage.
    pub fn move_to_storage(self, resource: Resource<'_>, limit: u32) {
        sys::move_to_storage(self.handle, resource, limit);
    }

    /// Moves at most `limit` (1..=4,096) matching units from storage into this machine.
    pub fn move_from_storage(self, resource: Resource<'_>, limit: u32) {
        sys::move_from_storage(self.handle, resource, limit);
    }
}

/// Iterator over the machines selected by [`Rule::machines`].
#[derive(Clone, Debug)]
pub struct Machines<'cx> {
    next: i32,
    end: i32,
    _rule: PhantomData<&'cx Rule>,
}

impl<'cx> Iterator for Machines<'cx> {
    type Item = Machine<'cx>;

    fn next(&mut self) -> Option<Machine<'cx>> {
        (self.next < self.end).then(|| {
            self.next += 1;
            Machine {
                handle: self.next - 1,
                _rule: PhantomData,
            }
        })
    }

    fn size_hint(&self) -> (usize, Option<usize>) {
        let remaining = (self.end - self.next).max(0) as usize;
        (remaining, Some(remaining))
    }
}

impl ExactSizeIterator for Machines<'_> {}
